// ─── SCENE 3: CTA — "Free Trial in Bio" ──────────────────────────────────────
const SceneThree: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgProgress = spring({ frame, fps, delay: 0, config: { damping: 200 } });
  const logoProgress = spring({ frame, fps, delay: 10, config: { damping: 200 } });
  const line1Progress = spring({ frame, fps, delay: 22, config: { damping: 200 } });
  const line2Progress = spring({ frame, fps, delay: 36, config: { damping: 200 } });
  const ctaProgress = spring({ frame, fps, delay: 55, config: { damping: 200 } });
  const arrowProgress = spring({ frame, fps, delay: 72, config: { damping: 200 } });

  // Pulsing arrow bounce
  const arrowBounce = interpolate(Math.sin(frame * 0.18), [-1, 1], [-12, 12]);

  // CTA glow pulse
  const ctaGlow = interpolate(Math.sin(frame * 0.12), [-1, 1], [0.6, 1.0]);

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
