        {/* Headline */}
        <div
          style={{
            opacity: line1Progress,
            transform: `translateY(${interpolate(line1Progress, [0, 1], [70, 0])}px)`,
            fontSize: 136,
            fontWeight: 900,
            color: COLORS.white,
            letterSpacing: "-0.03em",
            textAlign: "center",
            lineHeight: 1.0,
            marginBottom: 16,
