// ─── MAIN COMPOSITION ─────────────────────────────────────────────────────────
const scene1Dur = 200;
const scene2Dur = 175;
const scene3Dur = 165;
const openBlack = 20;
const closeBlack = 25;

// Total = openBlack + T + scene1 + T + scene2 + T + scene3 + T + closeBlack - overlaps
// TransitionSeries overlap: each transition subtracts its own frames
// Total sequences: 20 + 200 + 175 + 165 + 25 = 585
// Transitions: 15*4 = 60
// Net: 585 - 60 = 525 ... but TransitionSeries handles overlap automatically
// exported durationInFrames = sum of all sequence durations - sum of transition durations
export const durationInFramesCalc =
  openBlack + scene1Dur + scene2Dur + scene3Dur + closeBlack - TRANSITION * 4;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {/* Opening black */}
      <TransitionSeries.Sequence durationInFrames={openBlack}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 1: Hook */}
      <TransitionSeries.Sequence durationInFrames={scene1Dur}>
        <SceneOne />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 2: Features */}
      <TransitionSeries.Sequence durationInFrames={scene2Dur}>
        <SceneTwo />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 3: CTA */}
      <TransitionSeries.Sequence durationInFrames={scene3Dur}>
        <SceneThree />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Closing black */}
      <TransitionSeries.Sequence durationInFrames={closeBlack}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
